---@language GLSL
local blur_vs = [[
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif // GL_FRAGMENT_PRECISION_HIGH

attribute vec2 position;

varying vec2 textureCoord;
varying vec4 coord1;
varying vec4 coord2;
varying vec4 coord3;

uniform vec2 offset;
//vec2 textureSize = vec2(360.,640.);
//vec2 textelSize = vec2(1.0/180.,1.0/320.);
vec2 textelSize = vec2(1./180.,1./320.);
void main()
{
    textureCoord = position*.5+.5;
    gl_Position = vec4(position, 0.,1.);

    coord1 = textureCoord.xyxy + offset.xyxy * vec4(1.,1.,-1.,-1.) * textelSize.xyxy;
    coord2 = textureCoord.xyxy + offset.xyxy * vec4(2.,2.,-2.,-2.) * textelSize.xyxy;
    coord3 = textureCoord.xyxy + offset.xyxy * vec4(3.,3.,-3.,-3.) * textelSize.xyxy;
}
]]


---@language GLSL
local blur_fs = [[
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif // GL_FRAGMENT_PRECISION_HIGH

uniform sampler2D inputImageTexture;
//uniform vec2 sz;
varying vec2 textureCoord;
varying vec4 coord1;
varying vec4 coord2;
varying vec4 coord3;



void main() {
    vec4 result = vec4(0.0);

    result += texture2D(inputImageTexture,coord3.xy) * 0.0205;
    result += texture2D(inputImageTexture,coord2.xy) * 0.0855;
    result += texture2D(inputImageTexture,coord1.xy) * 0.232;
    result += texture2D(inputImageTexture,textureCoord) * 0.324;
    result += texture2D(inputImageTexture,coord1.zw) * 0.232;
    result += texture2D(inputImageTexture,coord2.zw) * 0.0855;
    result += texture2D(inputImageTexture,coord3.zw) * 0.0205;

    gl_FragColor = result;
}
]]


