Comic = {}

function Comic:matchWithId(effectId)
    return 'KFM KSkr Comic' == effectId
end

function Comic.createWithId(effectId)
    if not Comic:matchWithId(effectId) then
        return nil
    end

    local o = {
        program = {},
        cachedFbos = {},
        vertexBuffer = 0
    }
    o = newObject(o, Comic)
    o:init()
    return o;
end

function Comic:takeCachedFrameBuffer(fboWidth, fboHeight)
    if AESP.takeCachedFrameBuffer ~= nil then
        return AESP:takeCachedFrameBuffer(fboWidth, fboHeight)
    end
    for i=1, #self.cachedFbos, 1 do
        local fbo = self.cachedFbos[i]
        if fbo._isHold == false and fbo._width == fboWidth and fbo._height == fboHeight then
            fbo._isHold = true
            return fbo
        end
    end

    local fbo = {
        _width = fboWidth,
        _height = fboHeight,
        _texId = 0,
        _fboId = 0,
        _isHold = false,

        width = function(self) return self._width end,
        height = function(self) return self._height end,
        texId = function(self) return self._texId end,
        fboId = function(self) return self._fboId end,

        init = function(self)
            self:release()
            self._texId = cgeGenBlackTexture(self._width, self._height, GL_RGBA)
            local buffer = {}
            glGenFramebuffers(1, buffer)
            self._fboId = buffer[1]
            glBindFramebuffer(GL_FRAMEBUFFER, self._fboId)
            glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, GL_TEXTURE_2D, self._texId, 0);
        end,

        release = function(self)
            if self._texId ~= 0 then glDeleteTextures(1, {self._texId}) end
            if self._fboId ~= 0 then glDeleteFramebuffers(1, {self._fboId}) end
            self._texId = 0
            self._fboId = 0
        end,

        bind = function(self) 
            glBindFramebuffer(GL_FRAMEBUFFER, self._fboId);
            glViewport(0, 0, self._width, self._height);
        end
    }
    fbo:init()
    fbo._isHold = true
    self.cachedFbos[#self.cachedFbos + 1] = fbo
    return fbo
end

function Comic:recycleCachedFrameBuffer(fbo)
    if AESP.recycleCachedFrameBuffer ~= nil then
        return AESP:recycleCachedFrameBuffer(fbo)
    end
    fbo._isHold = false
end

function Comic:resize(width,height)

end

function Comic:init()
    local buffer = {}
    glGenBuffers(1, buffer)
    self.vertexBuffer=buffer[1]

    local vertexBufferData = CGE.FloatBuffer:alloc(8)
    vertexBufferData:put(8, { -1, -1, 1, -1, -1, 1, 1, 1}, 0)
    glBindBuffer(GL_ARRAY_BUFFER, self.vertexBuffer)
    glBufferData(GL_ARRAY_BUFFER, 8, vertexBufferData, GL_STATIC_DRAW)


    self.program = CGE.ProgramObject()
    self.program:bindAttribLocation("vPosition", 0)
    self.program:initWithShaderStrings(s_vsh, final_fsh)

    self.blurProgram = CGE.ProgramObject()
    self.blurProgram:bindAttribLocation("position",0)
    self.blurProgram:initWithShaderStrings(blur_vs,blur_fs)

    -- self.blurFbo_H = CGE.FrameBuffer()
    -- self.blurFbo_V = CGE.FrameBuffer()
    -- self.blurFboTextures = {0,0}

    self.comicProgram = CGE.ProgramObject()
    self.comicProgram:bindAttribLocation("vPosition", 0)
    self.comicProgram:initWithShaderStrings(comic_vsh, comic_fsh)
    self.comicProgram:bind()
    self.comicProgram:sendUniformi('inputImageTexture', 0)
    self.comicProgram:sendUniformi('inputImageTexture1', 1)

end

function Comic:valueType(index)
    if index == 1 then
        return FM.AEValueType_OneDInt
    elseif index == 2 or index == 3 then
        return FM.AEValueType_ThreeD
    else
        return FM.AEValueType_OneDFloat
    end
    return FM.AEValueType_No_Value
end

function Comic:updateValue(index, val1, val2, val3)
    self.comicProgram:bind()
    if index == 1 then
        self.comicProgram:sendUniformi("comicType", val1)
    elseif index == 2 then
    --    self.bleed_length = val1
        self.comicProgram:sendUniformf("color1", val1,val2,val3)
      
    elseif index == 3 then
        self.comicProgram:sendUniformf("color2", val1,val2,val3)
      
    elseif index == 4 then
        self.comicProgram:sendUniformf("gridNumRatio",val1)
       
    end
end

function Comic:drawBlurEffect(textID, blurFbo_H, blurFbo_V)
    glViewport(0,0,self.width/4,self.height/4)

    -- glBindFramebuffer(GL_FRAMEBUFFER, self.blurFbo_H:getID())
    blurFbo_H:bind()
    glBindBuffer(GL_ARRAY_BUFFER, self.vertexBuffer)
    glEnableVertexAttribArray(0)
    glVertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 0, 0)
    glActiveTexture(GL_TEXTURE0)
    glBindTexture(GL_TEXTURE_2D, textID)
    self.blurProgram:bind()
    self.blurProgram:sendUniformf('offset',0.15,0.0)
    glDrawArrays(GL_TRIANGLE_STRIP, 0, 4)


    blurFbo_V:bind()
    -- glBindFramebuffer(GL_FRAMEBUFFER, self.blurFbo_V:getID())
    glBindBuffer(GL_ARRAY_BUFFER, self.vertexBuffer)
    glEnableVertexAttribArray(0)
    glVertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 0, 0)
    glActiveTexture(GL_TEXTURE0)
    glBindTexture(GL_TEXTURE_2D, blurFbo_H:texId())
    self.blurProgram:bind()
    self.blurProgram:sendUniformf('offset',0.0,0.15)
    glDrawArrays(GL_TRIANGLE_STRIP, 0, 4)


    glViewport(0,0,self.width,self.height)
end

function Comic:render(outFBO, inputTex)

    ---获取当前画布的size
    local viewport = {}
    glGetIntegerv(GL_VIEWPORT, 4, viewport)

    self.width = viewport[3]
    self.height = viewport[4]

    ---先来一遍模糊
    -- if self.blurFboTextures[1] == 0 then
    --     self.blurFboTextures[1] = cgeGenBlackTexture(self.width/4, self.height/4, GL_RGBA)
    --     self.blurFbo_H:bindTexture2D(self.blurFboTextures[1])
    -- end

    -- if self.blurFboTextures[2] == 0 then
    --     self.blurFboTextures[2] = cgeGenBlackTexture(self.width/4 ,self.height/4 ,GL_RGBA)
    --     self.blurFbo_V:bindTexture2D(self.blurFboTextures[2])
    -- end

    local blurFbo_H = self:takeCachedFrameBuffer(self.width/4, self.height/4)
    local blurFbo_V = self:takeCachedFrameBuffer(self.width/4, self.height/4)
    self:drawBlurEffect(inputTex, blurFbo_H, blurFbo_V)

    ----画完blur效果，此时纹理self.blurFboTextures[2]为高斯模糊后的效果



    glBindFramebuffer(GL_FRAMEBUFFER, outFBO)
    glBindBuffer(GL_ARRAY_BUFFER, self.vertexBuffer)
    glEnableVertexAttribArray(0)
    glVertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 0, 0)
    glActiveTexture(GL_TEXTURE0)
    glBindTexture(GL_TEXTURE_2D, inputTex)
    glActiveTexture(GL_TEXTURE1)
    -- glBindTexture(GL_TEXTURE_2D,self.blurFboTextures[2])
    glBindTexture(GL_TEXTURE_2D, blurFbo_V:texId())
    self.comicProgram:bind()
    self.comicProgram:sendUniformi('imageWidth',self.width)
    self.comicProgram:sendUniformi('imageHeight',self.height)
    glDrawArrays(GL_TRIANGLE_STRIP, 0, 4)

    self:recycleCachedFrameBuffer(blurFbo_H);
    self:recycleCachedFrameBuffer(blurFbo_V);
end

function Comic:onDestroy()
    ---释放资源

    -- glDeleteTextures(2,self.blurFboTextures)
    glDeleteBuffers(1,{self.vertexBuffer})
    --glDeleteBuffers(2,{self.blurFbo_H:getID(),self.blurFbo_V:getID()})
    for i=1, #self.cachedFbos, 1 do
        self.cachedFbos[i]:release()
    end
    self.cachedFbos = {}
end